#!/bin/bash
# 场景图 v3：按《场景质量标准 v1》（11-02 13:33）。13:39 测 H1；13:43 Rhett「按新标准把一组都生成出来」批准全组。
cd /workspace/work/.agents/skills/credit-media-skill
export CREDIT_MEDIA_API_KEY=proxy
O=/workspace/projects/04b4b2af-0042-4c1b-a4f3-cdc315529fa5/promo/scenes_v3; KV=$O/../keyvisual_v1
PRE="写实电影级场景概念图，16:9宽银幕横构图，与参考图同一质感「暗岩传说」，供游戏开发按图搭建场景：结构清楚、可读。无人物或只有极小人物剪影提供尺度。"
STD="【光影】主光、补光、关键点光逻辑清楚，冷暖对比明确；【雾】分层体积雾，近处淡、远处浓，雾色随区域调色，不要全局一层灰雾；【材质】高清真实PBR质感：湿石有高光反光、干土哑光、铜器有铜绿锈、石缝有苔藓、潮痕与水渍、裂纹，墙角石缝与物件接地处有明显接触暗角，物件不能浮在地面上；【布景】近景/中景/远景层次分明：前景地表碎件与叙事小道具，中景小礁与灌木，远景大件地标，边缘自然过渡，不留大片空地；【水面】有清晰倒影。"
NEG="画面中不要出现任何文字、字幕、水印、UI；不要卡通；不要过度锐化或塑料感。"
gen(){ n=$1; p=$2; shift 2; a=(); for i in "$@"; do a+=(--image "$i"); done
  bash scripts/run.sh image --model gpt-image-2 --size 1536x1024 --quality high --prompt "$PRE $p $STD $NEG" "${a[@]}" --out $O/$n.png > $O/$n.log 2>&1 & }
gen S2_coast_v4 "地底之海世界观：头顶是岩石穹顶，没有天空。沉钟海岸，低机位沿岸视角。【主色调】幽绿灰海色，铜绿与暖黄灯点。【光源】主光=穹顶裂缝漏下的冷灰青光；补光=海面幽绿荧光；关键点光=码头暖黄灯笼、远处灯塔光束。【雾】近处浪沫水汽，中景低云般青雾，远处浓雾吞没海平线。【地标】退潮浅滩上半埋一口巨大铜绿古钟，钟口朝天积满海水。【近景】湿黑卵石与潮痕、藤壶、海藻、断锁链、碎钟片、半埋鲸骨。【中景】锈铁锚码头、木栈、缆绳。【远景】只有巨鲸骨礁、六棱玄武岩柱群、一座孤立灯塔和穹顶岩壁；远景绝对不要任何城市、城堡、哥特尖塔建筑群。" $KV/ref/style_B.jpg
gen B5_redsand_v4 "赤砂裂谷，平视。【主色调】赤红砂岩与金黄，阴影偏紫。【光源】主光=烈日斜光；补光=砂岩反射的暖红光；关键点光=王陵入口内的火盆。【雾】近处卷沙，中景热浪扭曲，远处浓沙雾。【地标】画面中心是一尊高约40米的巨大法老坐像，头戴条纹头巾与蛇形冠，面部清晰，下半身半埋沙中，是画面最显眼的主体；两侧崖壁开凿王陵入口。【近景】风化石块、半埋陶罐、骨骸、沙纹。【中景】石像、残柱。【远景】峡谷尽头。" $KV/ref/style_B.jpg
gen B6_frostridge_v4 "霜脊高地，平视风雪。【主色调】冷白灰蓝，幽蓝魂灯为点。【光源】主光=灰白漫射天光；补光=冰面反光；关键点光=古墓大门两侧幽蓝魂灯。【雾】近处飞雪，中景风雪雾，远处浓白雪雾。【地标】画面中下方是一片透明冰湖，冰面下清晰可见一座巨大的石刻古墓穴双开大门，门上浮雕与封印纹发幽蓝光，从冰面透出，是画面最显眼的主体；冰晶尖塔刺向灰白天空。【近景】冰裂纹、积雪、冻住的锁链与旗杆、冰下气泡。【中景】冰湖。【远景】冰晶尖塔与山脊。" $KV/ref/style_B.jpg
gen B7_emberwaste_v4 "烬落荒原，俯视3/4。【主色调】焦黑灰与熔红橙。【光源】主光=暗红天光；补光=地缝熔岩向上照；关键点光=铸造厂橙色炉口、火山口石门内熔光。【雾】近处余烬火星，中景灰烟，远处浓黑烟。【地标】画面正中是一座火山，整个火山口被凿成一张巨大的石雕王座形状（有扶手和高靠背轮廓），王座座面处开一道巨大石门，门内喷出熔光（熔心王座），轮廓一眼可认，不是城堡；左远景高烟囱林立、仍在运转的铸造厂。【近景】焦土裂缝熔岩网、碎岩、烧焦木桩、锈链。【中景】右侧一角石墙与旗帜的据点。【远景】王座石门。" $KV/ref/style_B.jpg
wait
